#include <cmath>
#include <cstdio>
#include <vector>
#include <algorithm>
int main(int argc,char**argv){if(argc!=3)return 2;const int ns=1000,nf=100000;std::vector<float>x(ns),y(ns),f(nf);std::vector<double>expected(nf);for(int i=0;i<ns;i++)x[i]=0.01f+i*(31.4f-0.01f)/ns;for(int i=0;i<ns;i++)y[i]=2.f*sinf(1.f*x[i]+1.57f);for(int i=0;i<nf;i++)f[i]=0.01f+i*(10.f-0.01f)/nf;float scale=2.f/1.5f;double mindet=INFINITY,energy=0;for(float v:y)energy+=(double)v*v;for(int k=0;k<nf;k++){double xc=0,xs=0,cc=0,ss=0,cs=0;for(int i=0;i<ns;i++){double a=(double)f[k]*x[i],s=sin(a),c=cos(a);xc+=(double)y[i]*c;xs+=(double)y[i]*s;cc+=c*c;ss+=s*s;cs+=c*s;}double det=cc*ss-cs*cs;mindet=fmin(mindet,det);if(!(det>0))return 3;expected[k]=0.5*(double)scale*(ss*xc*xc-2*cs*xc*xs+cc*xs*xs)/det;if(!std::isfinite(expected[k])||expected[k]<0)return 4;}FILE*a=fopen(argv[1],"wb");if(!a)return 5;fwrite(x.data(),4,ns,a);fwrite(y.data(),4,ns,a);fwrite(f.data(),4,nf,a);fwrite(&scale,4,1,a);fclose(a);FILE*d=fopen(argv[2],"wb");if(!d)return 6;fwrite(expected.data(),8,nf,d);fclose(d);int peak=std::max_element(expected.begin(),expected.end())-expected.begin();printf("{\"samples\":1000,\"frequencies\":100000,\"frequency_unit\":\"angular_radians_per_input_time_unit\",\"input_sampling\":\"uniform_source_formula\",\"scale_float32\":%.12g,\"actual_energy\":%.17g,\"energy_projection_bound\":%.17g,\"minimum_Gram_determinant\":%.17g,\"Float64_peak_frequency\":%.12g,\"Float64_peak_power\":%.17g,\"oracle\":\"IndependentDouble2x2Gramleastsquares,noatan2/taurotation\"}\n",scale,energy,0.5*(double)scale*energy,mindet,f[peak],expected[peak]);return 0;}
